style.css:
@-moz-document domain("roblox.com") {
/* Set custom background image */
    body, html {
        background: url("https://wallpapercave.com/wp/wp5126415.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        color: #e0e0e0 !important;
    }

    /* Dark UI elements */
    .navbar, .header, .navigation, #navigation,
    .container-main, .content, .game-home-page,
    .game-card-container, .game-tile, .thumbnail-2d-container,
    .footer, .rbx-header {
        background-color: rgba(18, 18, 18, 0.85) !important;
        color: #e0e0e0 !important;
    }

    /* Game cards */
    .game-card-container, .game-tile {
        border: 1px solid #333 !important;
    }

    /* Text and links */
    a {
        color: #64b5f6 !important;
    }

    /* Buttons */
    .btn-primary, .btn-secondary, .btn-control-md {
        background-color: #2c2c2c !important;
        border-color: #444 !important;
        color: #fff !important;
    }

    .btn-primary:hover, .btn-secondary:hover {
        background-color: #444 !important;
    }

    /* Remove ads or promos */
    .ad-container, .abp, .sponsored-game {
        display: none !important;
    }

    /* Semi-transparent content background for readability */
    .content, .container-main, .games-page, .section {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }
}
